package com.amit.jobagent.application;
import com.amit.jobagent.audit.*;import com.amit.jobagent.common.api.PagedResponse;import com.amit.jobagent.common.error.*;import com.amit.jobagent.matching.*;import com.amit.jobagent.profile.ActiveProfileProvider;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.*;import java.util.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ApplicationReviewService{
 private final ApplicationPackageRepository packages;private final ApplicationPackageRevisionRepository revisions;private final ApplicationQuestionDraftRepository questions;private final GeneratedContentRepository contents;private final GeneratedClaimRepository claims;private final ApplicationReviewDecisionRepository decisions;private final ApplicationPackageMapper mapper;private final ActiveProfileProvider profiles;private final CompletedEvaluationProvider evaluations;private final com.amit.jobagent.job.JobMatchingProvider jobs;private final HandoffEligibilityService eligibility;private final AuditService audit;private final ObjectMapper json;
 ApplicationReviewService(ApplicationPackageRepository p,ApplicationPackageRevisionRepository r,ApplicationQuestionDraftRepository q,GeneratedContentRepository c,GeneratedClaimRepository g,ApplicationReviewDecisionRepository d,ApplicationPackageMapper m,ActiveProfileProvider ap,CompletedEvaluationProvider e,com.amit.jobagent.job.JobMatchingProvider j,HandoffEligibilityService h,AuditService a,ObjectMapper o){packages=p;revisions=r;questions=q;contents=c;claims=g;decisions=d;mapper=m;profiles=ap;evaluations=e;jobs=j;eligibility=h;audit=a;json=o;}
 @Transactional public ApplicationReviewResponse get(UUID packageId,UUID revisionId){ownedRevision(packageId,revisionId);refreshInvalidation(packageId,revisionId);var r=ownedRevision(packageId,revisionId);return response(packageId,r);}
 @Transactional(readOnly=true)public PagedResponse<ReviewQueueItem>queue(ReviewStatus status,Recommendation recommendation,String company,Boolean stale,LocalDate from,LocalDate to,int page,int size){if(page<0||size<1||size>100)throw new DomainValidationException("Page must be non-negative and size must be between 1 and 100");var all=new ArrayList<ReviewQueueItem>();for(var p:packages.findByCandidateIdOrderByCreatedAtDesc(profiles.requireProfileId())){if(p.currentRevisionId==null)continue;var r=revisions.findById(p.currentRevisionId).orElse(null);if(r==null||!(r.reviewStatus==ReviewStatus.PENDING_REVIEW||r.reviewStatus==ReviewStatus.CHANGES_REQUESTED||r.reviewStatus==ReviewStatus.INVALIDATED||p.status==ApplicationPackageStatus.STALE))continue;var job=jobs.require(p.jobId);Recommendation rec;try{rec=evaluations.require(r.evaluationId,p.jobId).recommendation();}catch(RuntimeException x){rec=null;}var item=new ReviewQueueItem(p.getId(),r.id,r.revisionNumber,job.title(),job.company(),rec,r.reviewStatus,p.status==ApplicationPackageStatus.STALE,p.staleReason,r.createdAt);if(status!=null&&item.reviewStatus()!=status||recommendation!=null&&item.recommendation()!=recommendation||company!=null&&!company.isBlank()&&!item.company().toLowerCase(Locale.ROOT).contains(company.trim().toLowerCase(Locale.ROOT))||stale!=null&&item.stale()!=stale||from!=null&&item.createdAt().isBefore(from.atStartOfDay().toInstant(ZoneOffset.UTC))||to!=null&&!item.createdAt().isBefore(to.plusDays(1).atStartOfDay().toInstant(ZoneOffset.UTC)))continue;all.add(item);}int start=Math.min(page*size,all.size()),end=Math.min(start+size,all.size());return new PagedResponse<>(List.copyOf(all.subList(start,end)),page,size,all.size(),(all.size()+size-1)/size);}
 @Transactional public ApplicationReviewResponse decide(UUID packageId,UUID revisionId,ReviewDecisionType type,ReviewDecisionRequest request){Objects.requireNonNull(request,"request is required");var r=ownedRevision(packageId,revisionId);if(r.reviewRecordVersion!=request.reviewRecordVersion())throw new ConflictException("Review state changed; reload before deciding");String comment=sanitize(request.comment());if((type==ReviewDecisionType.CHANGES_REQUESTED||type==ReviewDecisionType.REJECTED)&&(comment==null||comment.isBlank()))throw new DomainValidationException("A review comment is required when requesting changes or rejecting");if(type==ReviewDecisionType.APPROVED_FOR_HANDOFF){if(!request.checklist().complete())throw new DomainValidationException("Every review checklist item must be confirmed before approval");var required=questions.findByRevisionIdOrderByCreatedAtAscIdAsc(r.id).stream().filter(q->q.classification==QuestionClassification.USER_INPUT_REQUIRED).map(q->q.id).toList();var resolutions=request.questionResolutions()==null?Map.<UUID,QuestionResolution>of():request.questionResolutions();if(required.stream().anyMatch(id->!resolutions.containsKey(id)))throw new DomainValidationException("Every USER_INPUT_REQUIRED question must be acknowledged, completed, or intentionally excluded");var check=eligibility.check(packageId,revisionId);var approvalBlocks=check.blockingReasons().stream().filter(x->!x.code().equals("REVISION_NOT_APPROVED")).toList();if(!approvalBlocks.isEmpty())throw new DomainValidationException("Approval blocked: "+approvalBlocks.stream().map(BlockingReason::message).reduce((a,b)->a+"; "+b).orElse("revision is ineligible"));String checklist=write(Map.of("checklist",request.checklist(),"questionResolutions",resolutions));var d=decisions.save(new ApplicationReviewDecision(r.id,type,actor(),role(),comment,checklist,r.jobChecksum,r.profileChecksum,r.evaluationChecksum,check.artifactManifestChecksum(),check.validationChecksum()));r.review(ReviewStatus.APPROVED_FOR_HANDOFF);revisions.saveAndFlush(r);audit.record(AuditEventType.APPLICATION_REVIEW_APPROVED,"ApplicationPackageRevision",r.id,write(Map.of("decisionId",d.id,"revisionNumber",r.revisionNumber)));return response(packageId,r);}ReviewStatus state=type==ReviewDecisionType.CHANGES_REQUESTED?ReviewStatus.CHANGES_REQUESTED:ReviewStatus.REJECTED;String snapshot=write(Map.of("checklist",request.checklist(),"questionResolutions",request.questionResolutions()==null?Map.of():request.questionResolutions()));var blocks=new ArrayList<BlockingReason>();String manifest=eligibility.artifactManifest(r.id,blocks);String validation=eligibility.validationChecksum(claimsFor(r.id),questions.findByRevisionIdOrderByCreatedAtAscIdAsc(r.id),r);var d=decisions.save(new ApplicationReviewDecision(r.id,type,actor(),role(),comment,snapshot,r.jobChecksum,r.profileChecksum,r.evaluationChecksum,manifest,validation));r.review(state);revisions.saveAndFlush(r);audit.record(type==ReviewDecisionType.CHANGES_REQUESTED?AuditEventType.APPLICATION_REVIEW_CHANGES_REQUESTED:AuditEventType.APPLICATION_REVIEW_REJECTED,"ApplicationPackageRevision",r.id,write(Map.of("decisionId",d.id,"revisionNumber",r.revisionNumber)));return response(packageId,r);}
 private void refreshInvalidation(UUID packageId,UUID revisionId){var r=ownedRevision(packageId,revisionId);if(r.reviewStatus!=ReviewStatus.APPROVED_FOR_HANDOFF&&r.reviewStatus!=ReviewStatus.INVALIDATED)return;String reason;if(r.reviewStatus==ReviewStatus.INVALIDATED){var p=packages.findById(packageId).orElseThrow();reason=p.staleReason==null?"APPROVAL_STATE_CHANGED":p.staleReason;}else{var check=eligibility.check(packageId,revisionId);if(check.eligible())return;reason=check.blockingReasons().stream().filter(x->!x.code().equals("REVISION_NOT_APPROVED")).map(BlockingReason::code).reduce((a,b)->a+","+b).orElse("APPROVAL_STATE_CHANGED");r.review(ReviewStatus.INVALIDATED);revisions.save(r);}var open=decisions.findByRevisionIdOrderByCreatedAtDesc(r.id).stream().filter(x->x.decision==ReviewDecisionType.APPROVED_FOR_HANDOFF&&x.invalidatedAt==null).toList();open.forEach(x->x.invalidate(reason));if(!open.isEmpty())audit.record(AuditEventType.APPLICATION_REVIEW_INVALIDATED,"ApplicationPackageRevision",r.id,write(Map.of("reason",reason)));}
 private ApplicationReviewResponse response(UUID packageId,ApplicationPackageRevision r){var history=decisions.findByRevisionIdOrderByCreatedAtDesc(r.id).stream().map(this::decisionResponse).toList();return new ApplicationReviewResponse(mapper.revision(r),r.reviewStatus,r.reviewRecordVersion,eligibility.check(packageId,r.id),history);}
 private ReviewDecisionResponse decisionResponse(ApplicationReviewDecision d){ReviewChecklist c;try{c=json.readTree(d.checklist).has("checklist")?json.treeToValue(json.readTree(d.checklist).get("checklist"),ReviewChecklist.class):json.readValue(d.checklist,ReviewChecklist.class);}catch(Exception x){c=new ReviewChecklist(false,false,false,false,false,false);}return new ReviewDecisionResponse(d.id,d.decision,d.actorId,d.actorRole,d.comment,c,d.createdAt,d.invalidatedAt,d.invalidationReason);}
 private List<GeneratedClaim>claimsFor(UUID revision){var cs=contents.findByRevisionIdOrderByOrderAscIdAsc(revision);return cs.isEmpty()?List.of():claims.findByContentIdIn(cs.stream().map(GeneratedContent::getId).toList());}private ApplicationPackageRevision ownedRevision(UUID pkg,UUID rev){UUID candidate=profiles.requireProfileId();var p=packages.findById(pkg).filter(x->x.candidateId.equals(candidate)).orElseThrow(()->new ResourceNotFoundException("Application package was not found"));return revisions.findByPackageIdAndId(p.getId(),rev).orElseThrow(()->new ResourceNotFoundException("Package revision was not found"));}private String write(Object value){try{return json.writeValueAsString(value);}catch(Exception x){return "{}";}}private static String sanitize(String value){if(value==null)return null;String v=value.replaceAll("[<>]","").replaceAll("[\\p{Cntrl}&&[^\\r\\n\\t]]","").trim();return v.length()>2000?v.substring(0,2000):v;}private static String actor(){var a=SecurityContextHolder.getContext().getAuthentication();return a==null?"system":a.getName();}private static String role(){var a=SecurityContextHolder.getContext().getAuthentication();return a==null?"SYSTEM":a.getAuthorities().stream().map(Object::toString).sorted().reduce((x,y)->x+","+y).orElse("AUTHENTICATED");}
}
